internal fun healthspanV2OracleOutput(): String {
    fun f(value: Double): String = String.format(Locale.US, "%.9f", if (value == 0.0) 0.0 else value)
    fun digest(value: String): String {
        var hash = 14695981039346656037UL
        for (unit in value) hash = (hash xor unit.code.toULong()) * 1099511628211UL
        return hash.toString(16)
    }
    val output = mutableListOf<String>()
    val ages = listOf(18.0,20.0,29.5,30.0,40.0,55.0,60.0,72.25,100.0)
    val sexes = listOf("male","female","","nonbinary","MALE")
    val samples = listOf(
        listOf(0.0,3.9,4.0,5.5,6.999,7.0,8.0,9.0,10.0,14.0),
        listOf(-1.0,0.0,59.9,60.0,65.0,70.0,75.1,80.9,85.25,90.0,100.0,140.0),
        listOf(-2.0,0.0,7.0,9.5,10.0,15.0,53.6,100.0,150.0,300.0,600.0,900.0),
        listOf(-2.0,0.0,7.0,9.5,10.0,15.0,53.6,100.0,150.0,300.0,600.0,900.0),
        listOf(-2.0,0.0,7.0,9.5,10.0,15.0,40.0,53.6,60.0,100.0,120.0,300.0),
        listOf(0.0,1999.0,2000.0,3553.0,5801.0,7842.0,8000.0,10901.0,15000.0),
        listOf(0.0,10.0,18.0,35.0,45.0,70.0,100.0),
        listOf(0.0,39.0,40.0,55.0,60.0,64.0,85.0,100.0,110.0),
        listOf(0.0,39.0,40.0,50.0,67.0,70.0,80.0,90.0,97.0,100.0),
    )
    for ((index,factor) in VitalityEngine.Factor.entries.withIndex()) {
        val lines = mutableListOf<String>()
        for (age in ages) for (sex in sexes) for (value in samples[index]) {
            lines += listOf(f(age),sex,f(value),f(VitalityEngine.target(factor,age,sex)),
                f(VitalityEngine.lnHazard(factor,value,age,sex))).joinToString("|")
        }
        output += "curve|${factor.raw}|${lines.size}|${digest(lines.joinToString("\n"))}"
    }
    var neutral = VitalityEngine.Inputs(40.0,"male")
    for (factor in VitalityEngine.Factor.entries) neutral = neutral.setting(factor,VitalityEngine.target(factor,40.0,"male"))
    val scenarios = listOf(neutral,
        VitalityEngine.Inputs(40.0,"male",sleepHours=8.0,sleepConsistency=90.0,zone13MinPerWeek=400.0,zone45MinPerWeek=60.0,strengthMinPerWeek=120.0,steps=11000.0,vo2max=55.0,restingHR=50.0,leanMassPct=85.0),
        VitalityEngine.Inputs(65.0,"female",sleepHours=4.0,sleepConsistency=55.0,zone13MinPerWeek=0.0,zone45MinPerWeek=0.0,strengthMinPerWeek=0.0,steps=1500.0,vo2max=10.0,restingHR=110.0,leanMassPct=35.0),
        VitalityEngine.Inputs(40.0,"male",sleepHours=7.0,steps=8000.0,restingHR=60.0),
        VitalityEngine.Inputs(0.0,sleepHours=7.0,steps=8000.0,restingHR=60.0),
        VitalityEngine.Inputs(40.0,sleepHours=7.0,steps=8000.0),
        VitalityEngine.Inputs(18.0,"male",sleepHours=9.0,sleepConsistency=100.0,zone13MinPerWeek=900.0,zone45MinPerWeek=100.0,strengthMinPerWeek=300.0,steps=30000.0,vo2max=100.0,restingHR=30.0,leanMassPct=100.0),
        VitalityEngine.Inputs(100.0,"female",sleepHours=2.0,sleepConsistency=0.0,zone13MinPerWeek=0.0,zone45MinPerWeek=0.0,strengthMinPerWeek=0.0,steps=0.0,vo2max=0.0,restingHR=150.0,leanMassPct=0.0),
    )
    for ((index,input) in scenarios.withIndex()) {
        val result = VitalityEngine.compute(input)
        if (result == null) { output += "result|$index|nil"; continue }
        output += "result|$index|${f(result.bodyAge)}|${f(result.ageDelta)}|${f(result.vitality)}|${result.factorsUsed}"
        output += "impacts|$index|"+result.impacts.joinToString(",") { "${it.factor.raw}:${f(it.years)}:${f(it.adjustment)}:${if(it.isMissing) 1 else 0}" }
    }
    val end = VitalityWindow.epochDay("2026-10-18")!!
    fun history(count: Int=200): List<VitalityWindow.Day> = (0 until count).mapNotNull { index ->
        if(index%17==5) null else VitalityWindow.Day(HRVStatus.dayString(end-count+1+index),
            restingHR=(55+index%9).toDouble(),sleepHours=6.2+(index%13).toDouble()/7,
            sleepConsistency=(60+index%35).toDouble(),steps=(6000+(index*347)%5100).toDouble(),
            vo2max=if(index%7==0) (45+index%5).toDouble() else null,measuredVO2max=if(index==150) 41.0 else null,
            zone13Min=if(index%3==0) 32.0 else 0.0,zone45Min=if(index%5==0) 6.0 else 0.0,
            strengthMin=if(index%8==0) 45.0 else 0.0,hasRecovery=true)
    }
    fun printWindow(label: String,days: List<VitalityWindow.Day>,lean: List<VitalityWindow.LeanMassPoint> = emptyList()) {
        val result = VitalityWindow.healthspan(days,"2026-10-18",38.0,"female",lean)
        if(result==null) { output += "window|$label|nil"; return }
        output += "window|$label|${f(result.current.bodyAge)}|${f(result.current.vitality)}|${f(result.projected.bodyAge)}|${f(result.paceOfAging)}|${result.recoveriesLast31}|${result.coveredDays}"
        for((name,input) in listOf("long" to result.longInputs,"recent" to result.recentInputs))
            output += "inputs|$label|$name|"+VitalityEngine.Factor.entries.joinToString(",") { factor -> input.value(factor)?.let(::f) ?: "nil" }
    }
    printWindow("base",history())
    printWindow("lean",history(),listOf(VitalityWindow.LeanMassPoint(HRVStatus.dayString(end-300),78.0),VitalityWindow.LeanMassPoint(HRVStatus.dayString(end-100),72.0),VitalityWindow.LeanMassPoint(HRVStatus.dayString(end-20),74.0),VitalityWindow.LeanMassPoint(HRVStatus.dayString(end+1),90.0)))
    printWindow("carry",history(),listOf(VitalityWindow.LeanMassPoint(HRVStatus.dayString(end-300),78.0)))
    printWindow("staleLean",history(),listOf(VitalityWindow.LeanMassPoint(HRVStatus.dayString(end-365),78.0)))
    for(count in listOf(20,21,31)) printWindow("gate$count",(0 until count).map { index -> VitalityWindow.Day(HRVStatus.dayString(end-index),restingHR=60.0,sleepHours=7.0,steps=8000.0,hasRecovery=true) })
    for(day in listOf("1970-01-01","1969-12-31","2000-03-01","2026-10-18","2026-10-19","2026-10-24","2026-10-25","garbage")) output += "sunday|$day|${VitalityWindow.sundayKey(day) ?: "nil"}"
    output += "sundays|"+VitalityWindow.sundays("2026-09-19","2026-10-19").joinToString(",")
    for(sport in listOf("Strength Training","Barre-3","F45 Training","baby/toddler wearing","BABY WEARING","Running","Core training")) output += "sport|$sport|${if(VitalityWindow.isStrengthSport(sport)) 1 else 0}"
    for(json in listOf("""{"z1":12.5,"z2":30.1,"z3":20,"z4":7.3,"z5":1.1}""","""{"z1":true,"zone4":50}""","""{"z1":"12"}""","not json")) {
        val zones = VitalityWindow.zoneMinutes(json,2873.0)
        output += "zones|"+(zones?.let { f(it.first)+","+f(it.second) } ?: "nil")
    }
    return output.joinToString("\n")
}
